<template><AdminCardList :data="items" row-key="id" title="name" :status="status" :fields="fields" :actions="actions" @action="handleAction"/></template>
<script setup lang="ts">import{Delete,Edit}from'@element-plus/icons-vue';import AdminCardList,{type AdminCardActionConfig,type AdminCardFieldConfig}from'@/components/admin/AdminCardList.vue';import type{RoleItem}from'../types';defineProps<{items:RoleItem[]}>();const emit=defineEmits<{(e:'edit',row:RoleItem):void;(e:'delete',row:RoleItem):void}>();const status=(row:object)=>{const role=row as RoleItem;return{label:role.status===1?'启用':'停用',type:role.status===1?'success' as const:'gray' as const}};const fields:AdminCardFieldConfig[]=[{label:'权限',value:(row)=>`${(row as RoleItem).permissions.length} 项`},{label:'管理员',value:(row)=>`${(row as RoleItem).admin_count} 人`},{label:'更新',prop:'updated_at'}];const actions:AdminCardActionConfig[]=[{key:'edit',label:'编辑',icon:Edit,type:'primary',plain:true},{key:'delete',label:'删除',icon:Delete,type:'danger',plain:true,visible:(row)=>(row as RoleItem).admin_count===0}];function handleAction(action:string,_key:string,row?:object){if(!row)return;if(action==='edit')emit('edit',row as RoleItem);if(action==='delete')emit('delete',row as RoleItem)}</script>
